args<-commandArgs(trailingOnly=TRUE);d<-args[1];lib<-args[2];.libPaths(c(lib,.Library));library(monocle);library(Matrix);set.seed(0)
x<-readMM(file.path(d,'counts.mtx'));cell<-read.delim(file.path(d,'cell_metadata.tsv'),row.names=1,check.names=FALSE);gene<-read.delim(file.path(d,'gene_metadata.tsv'),check.names=FALSE);rownames(gene)<-gene$gene_id;rownames(x)<-gene$gene_id;colnames(x)<-rownames(cell)
cds<-newCellDataSet(as(x,'dgCMatrix'),phenoData=new('AnnotatedDataFrame',data=cell),featureData=new('AnnotatedDataFrame',data=gene),expressionFamily=negbinomial.size());cds<-estimateSizeFactors(cds);cds<-setOrderingFilter(cds,readLines(file.path(d,'ordering_genes.txt')));cds<-reduceDimension(cds,max_components=2,reduction_method='DDRTree',norm_method='log',pseudo_expr=1,relative_expr=TRUE,verbose=TRUE);saveRDS(cds,file.path(d,'DDRTree_unrooted.rds'));xy<-t(reducedDimS(cds));stopifnot(identical(rownames(xy),rownames(cell)));write.table(cbind(cell_id=rownames(xy),xy),file.path(d,'DDRTree_coordinates.tsv'),sep='	',row.names=FALSE,quote=FALSE)
set.seed(0);z<-CytoTRACE::CytoTRACE(as.matrix(x),enableFast=TRUE,ncores=2,subsamplesize=1000);saveRDS(z,file.path(d,'CytoTRACE_official_result.rds'));tab<-data.frame(cell_id=names(z$CytoTRACE),CytoTRACE=z$CytoTRACE,detected_genes=z$Counts,GCS=z$GCS);write.table(tab,file.path(d,'cell_scores.tsv'),sep='	',row.names=FALSE,quote=FALSE);writeLines(z$filteredCells,file.path(d,'algorithm_filtered_cells.txt'));writeLines(capture.output(sessionInfo()),file.path(d,'sessionInfo.txt'))
